// FROZEN v2.4 tests (preregistrations/v2.4.md). Do not edit after first run.
import { mulberry, gauss, SEEDS, compare, item, Item, Cmp } from "./harness";
import * as M from "./v24mech";
const S = (salt: number, f: (r: () => number) => number) => SEEDS.map((s) => f(mulberry(s * 1009 + salt)));
const mean = (a: number[]) => a.reduce((p, x) => p + x, 0) / a.length;
const add = (name: string, ok: boolean, v = 0): Cmp => ({ control: "Additional: " + name, full: v, ctrl: 0, d: ok ? Infinity : 0, t: ok ? Infinity : 0, pass: ok });
const clip = (u: number, a: number) => Math.max(-a, Math.min(a, u));
export function v24Tests(): Item[] { const P = "Prereg v2.4"; const out: Item[] = [];
  { const run = (full: boolean) => S(9, (r) => { const phi = r() * 6.283185307; const ctl = M.homeoCtl(); let x = 0, ok = 0; for (let t = 0; t < 1000; t++) { const T = 2 * Math.sin(6.283185307 * t / 500 + phi) + 0.002 * t + 0.1 * gauss(r); const u = full ? clip(ctl(x), 0.3) : 0; x = x + 0.1 * (T - x) + u; if (Math.abs(x) < 0.5) ok++; } return ok / 1000; });
    const F = run(true), C = run(false); out.push(item("RM-9", P, "Homeostatic regulation (roadmap 9)", "fraction of steps in band", "PI thermostat", [compare("open loop", F, C), add("full ≥ 2× control", mean(F) >= 2 * mean(C), mean(F))])); }
  { let bmin = Infinity; const run = (full: boolean) => S(29, (r) => { const wA = Array.from({ length: 6 }, () => gauss(r)), wB = Array.from({ length: 6 }, () => gauss(r)); const smp = (k: number) => { const x = Array.from({ length: 8 }, () => gauss(r)); const y = k === 0 ? wA.reduce((s, w, i) => s + w * x[i], 0) : wB.reduce((s, w, i) => s + w * x[i + 2], 0); return { x, y }; };
      let L: { pred: (x: number[], k: number) => number; train: (x: number[], k: number, y: number) => void }; if (full) L = M.gatedLearner(); else { const w = new Array(8).fill(0); L = { pred: (x) => x.reduce((s, v, i) => s + v * w[i], 0), train(x, _k, y) { const e = y - this.pred(x, 0); for (let i = 0; i < 8; i++) w[i] += 0.05 * e * x[i]; } }; }
      for (let k = 0; k < 2; k++) for (let i = 0; i < 400; i++) { const d = smp(k); L.train(d.x, k, d.y); }
      const r2 = (k: number) => { const D = Array.from({ length: 500 }, () => smp(k)); const my = mean(D.map((d) => d.y)); const v = mean(D.map((d) => (d.y - my) ** 2)); return 1 - mean(D.map((d) => (d.y - L.pred(d.x, k)) ** 2)) / v; };
      const a = r2(0), b = r2(1); if (full) bmin = Math.min(bmin, b); return a; });
    const F = run(true), C = run(false); out.push(item("RM-29", P, "Lifelong learning without catastrophic forgetting (roadmap 29)", "task-A R² after task B", "context-dependent gating of readout", [compare("plain SGD", F, C), add("full retention ≥ 0.8 and task-B R² ≥ 0.8", mean(F) >= 0.8 && bmin >= 0.8, bmin)])); }
  { const run = (full: boolean) => S(36, (r) => { const p = [0.2, 0.4, 0.6, 0.8]; for (let i = 3; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [p[i], p[j]] = [p[j], p[i]]; } const w = [0, 0, 0, 0]; const g = M.daGate(); let tot = 0;
      for (let t = 0; t < 300; t++) { const e = w.map((v) => Math.exp(3 * v)); const z = e.reduce((a, b) => a + b); let u = r() * z, a = 0; while (u > e[a] && a < 3) { u -= e[a]; a++; } const rw = r() < p[a] ? 1 : 0; w[a] += 0.1 * (full ? g(rw) : 1); if (t >= 200) tot += rw; } return tot / 100; });
    out.push(item("RM-36", P, "Neuromodulated plasticity (roadmap 36)", "mean reward, trials 200–299", "dopamine-like RPE gate", [compare("ungated Hebbian", run(true), run(false))])); }
  { let lc = 0; const run = (full: boolean) => S(42, (r) => { let s = 0, n = 0; for (let t = 0; t < 200; t++) { const E = 0.2 + 1.8 * r(), D = 2 + Math.floor(r() * 9); const L = full && M.delayChoice(E, D); if (L) { n++; s += E > 0.1 * D ? 3 : 0; } else s += 1; } if (full) lc += n / 200 / 16; return s / 200; });
    const F = run(true), C = run(false); out.push(item("RM-42", P, "Delayed gratification (roadmap 42)", "mean payoff", "energy-budget gated waiting", [compare("myopic", F, C), add("larger-later ≥ 50% of trials", lc >= 0.5, lc)])); }
  { const run = (mode: string) => S(53, (r) => { const a0 = r() * 6.283185307; let x = 50 * Math.cos(a0), y = 50 * Math.sin(a0), h = r() * 6.283185307; const c = () => Math.exp(-Math.hypot(x, y) / 20) * (1 + 0.01 * gauss(r)); let cp = c();
      for (let t = 0; t < 300; t++) { x += Math.cos(h); y += Math.sin(h); const cn = c(); const pt = mode === "rand" ? 1 : M.tumbleP(mode === "full" ? cn - cp : 0); cp = cn; if (r() < pt) h = r() * 6.283185307; } return -Math.hypot(x, y); });
    const F = run("full"); out.push(item("RM-53", P, "Chemotaxis (roadmap 53)", "−final distance to source", "run-and-tumble temporal comparison", [compare("random walk", F, run("rand")), compare("ablated circuit (dc=0)", F, run("abl"))])); }
  { let lo = 0, hi = 0; const run = (full: boolean) => S(73, (r) => { let nl = 0, rl = 0, nh = 0, rh = 0; for (let t = 0; t < 400; t++) { const E = 2 * r(); const R = full ? M.riskChoice(E) : r() < 0.5; r(); if (E < 0.5) { nl++; rl += +R; } if (E > 1.5) { nh++; rh += +R; } } if (full) { lo += rl / nl / 16; hi += rh / nh / 16; } return rl / nl - rh / nh; });
    const F = run(true), C = run(false); out.push(item("RM-73", P, "Hunger-driven risk sensitivity (roadmap 73)", "P(risky|low E) − P(risky|high E)", "energy-budget rule", [compare("fixed policy", F, C), add("sign flip P(risky|low) > 0.5 > P(risky|high)", lo > 0.5 && hi < 0.5, lo - hi)])); }
  { const run = (full: boolean) => S(78, (r) => { const X: number[] = [], Y: number[] = []; for (const n of [4, 8, 16, 32]) { const e = Array.from({ length: 50 }, () => (full ? M.numEst(n, r) : n + 2 * gauss(r))); const m = mean(e); X.push(Math.log(n)); Y.push(Math.log(Math.sqrt(mean(e.map((v) => (v - m) ** 2))))); } const mx = mean(X), my = mean(Y); return X.reduce((s, x, i) => s + (x - mx) * (Y[i] - my), 0) / X.reduce((s, x) => s + (x - mx) ** 2, 0); });
    const F = run(true); out.push(item("RM-78", P, "Numerosity with Weber-law scaling (roadmap 78)", "slope of log sd vs log n", "log-scale noisy number code", [compare("flat noise", F, run(false)), add("mean slope in [0.7,1.3]", mean(F) >= 0.7 && mean(F) <= 1.3, mean(F))])); }
  { let endOk = true; const run = (full: boolean) => S(82, (r) => { const m = 0.8 + 0.4 * r(); let A: { trial: (u: number) => void; wait: (n: number) => void; resp: () => number }; if (full) A = M.bouton(); else { let V = 0; A = { trial: (u) => { V += 0.1 * (u - V); }, wait: () => {}, resp: () => V }; }
      for (let i = 0; i < 50; i++) A.trial(m); for (let i = 0; i < 50; i++) A.trial(0); const e = A.resp(); if (full && e >= 0.3 * m) endOk = false; A.wait(100); return A.resp() - e; });
    const F = run(true); out.push(item("RM-82", P, "Extinction and spontaneous recovery (roadmap 82)", "test response − end-of-extinction response", "two-process excitatory/inhibitory memory", [compare("Rescorla–Wagner unlearning", F, run(false)), add("end-of-extinction response < 0.3m", endOk)])); }
  { const run = (full: boolean) => S(96, (r) => { const g = Array.from({ length: 256 }, () => (r() < 0.5 ? 1 : 0)); const st = full ? M.tmr.encode(g) : g.slice(); if (st.length > 768) return -1; for (let t = 0; t < 100; t++) { for (let i = 0; i < st.length; i++) if (r() < 0.01) st[i] ^= 1; if (full) M.tmr.repair(st); } const d = full ? M.tmr.decode(st) : st; return mean(g.map((b, i) => +(b === d[i]))); });
    const F = run(true); out.push(item("RM-96", P, "Radiation-tolerant genome repair (roadmap 96)", "fraction of genome bits intact after 10× dose", "TMR majority scrubbing", [compare("no repair", F, run(false)), add("≥0.95 in ≥15/16 seeds", F.filter((x) => x >= 0.95).length >= 15)])); }
  { let rev = 0; const run = (full: boolean) => S(97, (r) => { const t0 = 150 + Math.floor(r() * 101); let E = 1, alive = 0, dorm = false; const sw = M.dormancy(); for (let t = 0; t < 2000; t++) { const food = !(t >= t0 && t < t0 + 1500); dorm = full ? sw(food) : false; E += (food ? 0.01 : 0) - (dorm ? 0.0002 : 0.002); if (E <= 0) break; alive++; } if (full && alive === 2000 && !dorm) rev++; return alive; });
    const F = run(true); out.push(item("RM-97", P, "Dormancy / cryptobiosis (roadmap 97)", "steps alive", "food-absence-triggered dormancy", [compare("no dormancy", F, run(false)), add("alive and active at t=2000 in ≥15/16", rev >= 15, rev)])); }
  { let p32 = 0; const run = (full: boolean) => S(52, (r) => { const Pk: number[] = []; for (let k = 0; k <= 56; k += 8) { const idx = Array.from({ length: 64 }, (_, i) => i); for (let i = 63; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [idx[i], idx[j]] = [idx[j], idx[i]]; } const alive = new Array(64).fill(true); idx.slice(0, k).forEach((i) => (alive[i] = false)); let se = 0; const ss: number[] = [];
      for (let n = 0; n < 200; n++) { const s = 2 * r() - 1; const a = full ? M.popCode.enc(s) : Array.from({ length: 64 }, (_, i) => (i === 0 ? s : 0)); const am = a.map((v, i) => (alive[i] ? v : 0)); const sh = full ? M.popCode.dec(am, alive) : am[0]; se += (s - sh) ** 2; ss.push(s); } const ms = mean(ss); Pk.push(1 - (se / 200) / mean(ss.map((v) => (v - ms) ** 2))); }
      if (full) p32 += Pk[4] / 16; let mx = -Infinity; for (let i = 0; i < Pk.length - 1; i++) mx = Math.max(mx, Pk[i] - Pk[i + 1]); return -mx; });
    const F = run(true); out.push(item("RM-52", P, "Graceful degradation under neuron loss (roadmap 52)", "−max drop in P(k) per 8 units lost", "distributed cosine population code", [compare("non-redundant code", F, run(false)), add("P(32) ≥ 0.5", p32 >= 0.5, p32)])); }
  return out; }
